import assert from 'node:assert/strict';
import {chromium} from 'playwright';
import {initialState,applyFirstWeekPlan,enrichTeachers} from '../../model.js';
import {applyTeacherDirectory} from '../../teacher-directory.js';
import {applyNewPresentationTeams} from '../../calendar-updates.js';
import {applyNovemberRoles} from '../../november-rotation.js';
import {websiteDefaults} from '../../website-settings.js';
import {INTERN_ACCESS_CODE} from '../../intern-access.js';
const origin='http://127.0.0.1:3000';
const project='https://esyhbmbbmktzvylgphxj.supabase.co';
const ownerId='82d08a21-3af2-4c4e-ace3-8c328ff8408b';
const planId='17a04ead-16cc-459e-a44c-8c504684b6f6';
let state=enrichTeachers(applyFirstWeekPlan(initialState()));
state.assignments=[];applyTeacherDirectory(state);applyNewPresentationTeams(state);applyNovemberRoles(state);
state.siteSettings={...websiteDefaults,homeHeading:'Initial saved heading'};
let revision=1,writes=0;
const requests=[];
const errors=[];
const browser=await chromium.launch({headless:true});
async function attach(context){
 await context.route(project+'/**',async route=>{
  const request=route.request(),url=new URL(request.url());
  requests.push({method:request.method(),path:url.pathname,select:url.searchParams.get('select')});
  const json=body=>route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(body)});
  if(url.pathname==='/auth/v1/user')return json({id:ownerId,email:'owner-test@example.org'});
  if(url.pathname==='/auth/v1/logout')return json({});
  if(url.pathname==='/rest/v1/plans'){
   if(request.method()==='PATCH'||request.method()==='POST'){
    const payload=request.postDataJSON();if(payload.state)state=payload.state;if(payload.revision)revision=payload.revision;else revision++;writes++;
   }
   const row={id:planId,owner_id:ownerId,state,revision,updated_at:new Date().toISOString()};
   if((url.searchParams.get('select')||'').startsWith('siteSettings:'))return json([{siteSettings:state.siteSettings,schoolDirectory:state.schoolDirectory||[]}]);
   return json([row]);
  }
  throw Error('Unexpected cloud request: '+request.method()+' '+url.pathname);
 });
 context.on('page',page=>page.on('pageerror',error=>errors.push(error.message)));
}
const student=await browser.newContext({viewport:{width:390,height:844}});
await attach(student);
const page=await student.newPage();
await page.goto(origin+'/index.html');
await page.locator('#school-portal select[name=school]').waitFor();
assert.equal(await page.locator('#planner-shell').isVisible(),false);
await page.locator('#school-portal button[type=submit]').click();
await page.locator('#intern-access-screen').waitFor();
assert.equal(requests.some(r=>r.path==='/rest/v1/plans'&&!r.select?.startsWith('siteSettings:')),false,'Calendar was fetched before intern code');
await page.locator('#intern-access-screen input[name=code]').fill('wrong');
await page.locator('#intern-access-screen button[type=submit]').click();
assert.match(await page.locator('#intern-access-error').textContent(),/did not match/);
assert.equal(await page.locator('#planner-shell').isVisible(),false);
await page.locator('#intern-access-screen input[name=code]').fill(INTERN_ACCESS_CODE);
await page.locator('#intern-access-screen button[type=submit]').click();
await page.waitForFunction(()=>document.querySelector('#title')?.textContent==='Initial saved heading');
assert.equal(await page.locator('[data-tab="manage-website"]').count(),0);
assert.equal(await page.locator('#manage-website').count(),0);
assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth+2),true,'Student mobile layout overflows');
await student.close();
const owner=await browser.newContext({viewport:{width:1440,height:1000}});
await attach(owner);
await owner.addInitScript(({project,ownerId})=>{
 localStorage.setItem('cuped-cloud-session',JSON.stringify({project_url:project,access_token:'review-test-access',refresh_token:'review-test-refresh',expires_at:Math.floor(Date.now()/1000)+3600,user:{id:ownerId}}));
},{project,ownerId});
const admin=await owner.newPage();
await admin.goto(origin+'/index.html?owner=1');
await admin.waitForFunction(()=>document.querySelector('#title')?.textContent==='Initial saved heading');
assert.equal(await admin.locator('#school-portal').count(),0);
await admin.locator('[data-tab="manage-website"]').click();
await admin.locator('#manage-website').waitFor({state:'visible'});
await admin.locator('#website-settings-form [name=homeHeading]').fill('Updated without ChatGPT');
await admin.locator('#website-settings-form [name=announcement]').fill('A public announcement edited in Owner');
await admin.locator('#website-settings-form [name=primaryColor]').fill('#26486f');
await admin.locator('#add-school-link').click();
await admin.locator('[name=schoolLinkName]').fill('Second school');
await admin.locator('[name=schoolLinkUrl]').fill('https://school-two.example.org/');
const before=writes;
await admin.locator('#preview-website').click();
await admin.locator('[data-tab=schedule]').click();
assert.equal(await admin.locator('#title').textContent(),'Updated without ChatGPT');
assert.equal(state.siteSettings.homeHeading,'Initial saved heading','Preview leaked into saved state');
assert.equal(writes,before,'Preview wrote to cloud');
await admin.locator('[data-tab="manage-website"]').click();
await admin.locator('#website-settings-form button[type=submit]').click();
for(let i=0;i<80&&state.siteSettings.homeHeading!=='Updated without ChatGPT';i++)await admin.waitForTimeout(100);
assert.equal(state.siteSettings.homeHeading,'Updated without ChatGPT');
assert.equal(state.siteSettings.announcement,'A public announcement edited in Owner');
assert.equal(state.schoolDirectory.find(s=>s.id!=='coral-reef').name,'Second school');
assert.ok(writes>before,'Settings did not save through existing sync');
await admin.setViewportSize({width:390,height:844});
assert.equal(await admin.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth+2),true,'Owner mobile layout overflows');
await owner.close();
const returning=await browser.newContext({viewport:{width:1280,height:900}});
await attach(returning);
const next=await returning.newPage();
await next.goto(origin+'/index.html');
await next.waitForFunction(()=>document.querySelector('#school-portal select')?.options.length===2);
assert.equal(await next.locator('#school-portal option').last().textContent(),'Second school');
await next.locator('#school-portal button[type=submit]').click();
await next.locator('#intern-access-screen input[name=code]').fill(INTERN_ACCESS_CODE);
await next.locator('#intern-access-screen button[type=submit]').click();
await next.waitForFunction(()=>document.querySelector('#title')?.textContent==='Updated without ChatGPT');
assert.equal(await next.locator('#calendar-announcement').textContent(),'A public announcement edited in Owner');
assert.equal(await next.locator('#manage-website').count(),0);
await returning.close();
await browser.close();
assert.deepEqual(errors,[]);
console.log('PASS: school chooser, code gate, no calendar reads before code, owner controls, preview isolation, synced save, returning student metadata and mobile layouts. All cloud writes were intercepted.');
